create table if not exists public.menu_categories(id bigint generated by default as identity primary key,slug text not null unique,name text not null,description text not null default '',icon text not null default '✦',image_url text not null default '',active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.menu_settings(id integer primary key default 1 check(id=1),cafe_name text not null default 'Testt Café',logo_url text not null default '',phone text not null default '',address text not null default '',instagram text not null default '',opening_hours text not null default '',currency text not null default 'تومان',menu_title text not null default 'منوی کافه',menu_subtitle text not null default 'قهوه، نوشیدنی، غذا و تجربه‌های امضادار',updated_at timestamptz not null default now());
alter table public.menu_categories enable row level security; alter table public.menu_settings enable row level security;
alter table public.products add column if not exists ingredients text not null default ''; alter table public.products add column if not exists discount_price numeric(12,2) null check(discount_price is null or discount_price>=0); alter table public.products add column if not exists image_url text not null default ''; alter table public.products add column if not exists available boolean not null default true; alter table public.products add column if not exists popular boolean not null default false; alter table public.products add column if not exists signature boolean not null default false; alter table public.products add column if not exists badge text not null default ''; alter table public.products add column if not exists sizes jsonb not null default '[]'::jsonb; alter table public.products add column if not exists addons jsonb not null default '[]'::jsonb; alter table public.products add column if not exists sort_order integer not null default 0;
alter table public.orders add column if not exists customer_phone text not null default ''; alter table public.orders add column if not exists table_number text not null default ''; alter table public.orders add column if not exists note text not null default '';
insert into public.menu_categories(slug,name,description,icon,sort_order) values('hot-drinks','نوشیدنی گرم','قهوه، چای و نوشیدنی‌های گرم ویژه','☕',10),('cold-drinks','نوشیدنی سرد','کولدبار، موکتل، اسموتی و نوشیدنی‌های خنک','✦',20),('fast-food','فست‌فود','برگر، پاستا، ساندویچ و فینگر فود','◈',30),('hookah','قلیان','طعم‌های کلاسیک، میوه‌ای و ترکیبی','◌',40),('desserts','دسر','دسرهای تازه و انتخاب‌های شیرین','◇',50),('signature','سیگنچر','انتخاب‌های ویژه و امضادار','★',60) on conflict(slug) do nothing;
insert into public.menu_settings(id) values(1) on conflict(id) do nothing;
drop policy if exists "Public can read active categories" on public.menu_categories; create policy "Public can read active categories" on public.menu_categories for select to anon,authenticated using(active=true or exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can insert categories" on public.menu_categories; create policy "Admins can insert categories" on public.menu_categories for insert to authenticated with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can update categories" on public.menu_categories; create policy "Admins can update categories" on public.menu_categories for update to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),'')))) with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can delete categories" on public.menu_categories; create policy "Admins can delete categories" on public.menu_categories for delete to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Public can read menu settings" on public.menu_settings; create policy "Public can read menu settings" on public.menu_settings for select to anon,authenticated using(true);
drop policy if exists "Admins can update menu settings" on public.menu_settings; create policy "Admins can update menu settings" on public.menu_settings for update to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),'')))) with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can read orders" on public.orders; create policy "Admins can read orders" on public.orders for select to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can update orders" on public.orders; create policy "Admins can update orders" on public.orders for update to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),'')))) with check(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
drop policy if exists "Admins can read order items" on public.order_items; create policy "Admins can read order items" on public.order_items for select to authenticated using(exists(select 1 from public.admins a where lower(a.email)=lower(coalesce((select auth.jwt()->>'email'),''))));
create or replace function public.set_menu_category_updated_at() returns trigger language plpgsql set search_path=public,pg_catalog as $$begin new.updated_at=now();return new;end;$$; drop trigger if exists menu_categories_set_updated_at on public.menu_categories; create trigger menu_categories_set_updated_at before update on public.menu_categories for each row execute function public.set_menu_category_updated_at();
create or replace function public.set_menu_settings_updated_at() returns trigger language plpgsql set search_path=public,pg_catalog as $$begin new.updated_at=now();return new;end;$$; drop trigger if exists menu_settings_set_updated_at on public.menu_settings; create trigger menu_settings_set_updated_at before update on public.menu_settings for each row execute function public.set_menu_settings_updated_at();
create or replace function public.place_order(p_customer_name text,p_customer_email text,p_items jsonb,p_customer_phone text default '',p_table_number text default '',p_note text default '') returns uuid language plpgsql security definer set search_path=public,pg_catalog as $$declare v_order_id uuid;v_total numeric(12,2);begin if char_length(trim(coalesce(p_customer_name,''))) not between 1 and 120 then raise exception 'Invalid customer name';end if;if char_length(trim(coalesce(p_customer_phone,''))) not between 3 and 30 then raise exception 'Invalid customer phone';end if;if char_length(trim(coalesce(p_table_number,'')))>30 then raise exception 'Invalid table number';end if;if char_length(trim(coalesce(p_note,'')))>1000 then raise exception 'Invalid order note';end if;if char_length(trim(coalesce(p_customer_email,'')))>320 then raise exception 'Invalid customer email';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Order must contain at least one item';end if;with requested as(select(item->>'id')::bigint product_id,greatest(1,least(99,(item->>'qty')::integer)) quantity from jsonb_array_elements(p_items)item)select coalesce(sum(coalesce(p.discount_price,p.price)*r.quantity),0) into v_total from requested r join public.products p on p.id=r.product_id where p.active=true and p.available=true;if v_total<=0 then raise exception 'No valid products in order';end if;insert into public.orders(customer_name,customer_email,customer_phone,table_number,note,total)values(trim(p_customer_name),lower(trim(coalesce(p_customer_email,''))),trim(p_customer_phone),trim(p_table_number),trim(p_note),v_total)returning id into v_order_id;insert into public.order_items(order_id,product_id,quantity,unit_price)select v_order_id,r.product_id,r.quantity,coalesce(p.discount_price,p.price) from(select(item->>'id')::bigint product_id,greatest(1,least(99,(item->>'qty')::integer)) quantity from jsonb_array_elements(p_items)item)r join public.products p on p.id=r.product_id where p.active=true and p.available=true;return v_order_id;end;$$;
revoke all on function public.place_order(text,text,jsonb) from public; revoke all on function public.place_order(text,text,jsonb,text,text,text) from public; grant execute on function public.place_order(text,text,jsonb,text,text,text) to anon,authenticated;